    $('favToggle').classList.toggle('active', showFavorites); $('favToggle').setAttribute('aria-pressed', String(showFavorites));
    document.querySelectorAll('[data-lab-shell]').forEach(b => b.classList.toggle('active', b.dataset.labShell === labShell));
    document.querySelectorAll('[data-task-shell]').forEach(b => b.classList.toggle('active', b.dataset.taskShell === taskShell));
    setText('terminalType', labShell === 'bash' ? 'Bash' : 'PowerShell'); setText('termPrompt', labShell === 'bash' ? '$' : 'PS >'); $('command').placeholder = labShell === 'bash' ? 'pwd' : 'Get-Location';
    renderCards(); renderTasks(); renderLabHelp(); renderExtras(); if (typeof renderLessonsV7 === 'function') renderLessonsV7(); if (typeof renderV8 === 'function') renderV8();
