function readFile(fs, p) { if (!fs.files.has(p)) return null; return fs.files.get(p) }
function argsAfter(ws, defaultName) { const pos = ws.findIndex((x, i) => i > 0 && !x.startsWith('-')); return pos < 0 ? defaultName : ws[pos] }
function labRun(input) { enhancedLabRun(input) }
function renderTasks() { let t = TASKS[taskShell], n = taskIndex[taskShell]; $('taskIndex').textContent = (n + 1) + ' / ' + t.length; setText('taskQuestion', t[n][lang === 'ar' ? 0 : lang === 'fr' ? 1 : 2]); let nav = $('taskNav'); nav.innerHTML = t.map((it, i) => `<button type="button" class="task-bubble ${solved[taskShell + ':' + i] ? 'solved' : ''} ${i === n ? 'current' : ''}" data-task="${i}" aria-label="Task ${i + 1}">${i + 1}</button>`).join(''); $('feedback').textContent = ''; $('feedback').classList.remove('error') }
function checkTask() {
    const f = $('feedback'); let current = lastRuns[taskShell]; if (!current) { f.textContent = T('noCommand'); f.classList.add('error'); return } let id = taskShell + ':' + taskIndex[taskShell], t = TASKS[taskShell][taskIndex[taskShell]];
    if (t[3].test(current.trim())) { let existed = Boolean(solved[id]); solved[id] = true; storage.set('shell-ultimate-solved', solved); f.classList.remove('error'); f.textContent = existed ? T('already') : T('correct'); setText('stat-passed', Object.keys(solved).filter(k => solved[k]).length); $('taskNav').querySelector('.current')?.classList.add('solved') }
    else { f.classList.add('error'); f.textContent = T('wrong') }
}
function start() {
    renderBase(); term(T('start'), 'hint');
    $('language').addEventListener('change', e => { lang = e.target.value; storage.set('shell-ultimate-lang', lang); renderBase() });
    $('theme').addEventListener('click', () => { theme = theme === 'light' ? 'dark' : 'light'; storage.set('shell-ultimate-theme', theme); renderBase() });
    document.querySelectorAll('.tab').forEach(b => b.addEventListener('click', () => selectTab(b.dataset.tab)));
    let searchFrame = 0; $('search').addEventListener('input', e => { keyword = e.target.value.trim(); limit = 16; cancelAnimationFrame(searchFrame); searchFrame = requestAnimationFrame(renderCards) });
    $('cat').addEventListener('change', e => { category = e.target.value; limit = 16; renderCards() });
    $('level').addEventListener('change', e => { level = e.target.value; limit = 16; renderCards() });
    document.querySelectorAll('[data-filter]').forEach(b => b.addEventListener('click', () => { filter = b.dataset.filter; limit = 16; renderBase() }));
    $('favToggle').addEventListener('click', () => { showFavorites = !showFavorites; limit = 16; renderBase() });
    $('loadMore').addEventListener('click', () => { limit += 16; renderCards() });
    $('cards').addEventListener('click', async e => {
        const b = e.target.closest('button[data-action]'); if (!b) return; let id = Number(b.dataset.id), c = COMMANDS.find(x => x.id === id); if (!c) return;
        if (b.dataset.action === 'lesson') { const match = LESSONS.find(l => l.shell === c.shell && l.refs.some(n => n.toLowerCase() === c.name.toLowerCase())); if (match) { v7Choose(match.id); selectTab('lessons') } return }
        if (b.dataset.action === 'note') { notes[id] = ($('note-' + id)?.value || '').slice(0, 5000); storage.set('shell-pro-notes', notes); toast(T('notesSaved')); renderCards(); return }
        if (b.dataset.action === 'expand') { expanded = expanded === id ? 0 : id; renderCards(); return }
        if (b.dataset.action === 'fav') { favorite[id] = !favorite[id]; storage.set('shell-ultimate-favorites', favorite); renderCards(); return }
        if (b.dataset.action === 'learn') { learned[id] = !learned[id]; storage.set('shell-ultimate-learned', learned); renderBase(); return }
        if (b.dataset.action === 'copy') { await copyText(c.example); toast(T('copied')); return }
        if (b.dataset.action === 'try') { labShell = c.shell; renderBase(); selectTab('lab'); $('command').value = c.example; $('command').focus(); return }
    });
    document.querySelectorAll('[data-lab-shell]').forEach(b => b.addEventListener('click', () => { labShell = b.dataset.labShell; $('terminalOutput').replaceChildren(); renderBase(); term(T('start'), 'hint') }));
    document.querySelectorAll('[data-task-shell]').forEach(b => b.addEventListener('click', () => { taskShell = b.dataset.taskShell; renderBase() }));
    $('terminalForm').addEventListener('submit', e => { e.preventDefault(); labRun($('command').value); $('command').value = ''; $('command').focus(); renderLabHelp() });
    $('labHelpBtn').addEventListener('click', () => { labRun('help') });
    $('labClearBtn').addEventListener('click', () => $('terminalOutput').replaceChildren());
    $('labResetBtn').addEventListener('click', () => { labRun('reset') });
    $('taskNav').addEventListener('click', e => { const b = e.target.closest('button[data-task]'); if (!b) return; taskIndex[taskShell] = Number(b.dataset.task); renderTasks() });
    $('taskNext').addEventListener('click', () => { taskIndex[taskShell] = (taskIndex[taskShell] + 1) % TASKS[taskShell].length; renderTasks() });
    $('taskCheck').addEventListener('click', checkTask);
    $('taskLab').addEventListener('click', () => { labShell = taskShell; selectTab('lab'); $('command').focus() });
    setupPro(); v4Setup(); if (typeof setupLessonsV7 === 'function') setupLessonsV7();
}
